            if(in_array($o['state'],['payment_pending','exception'],true)){self::form('staff_refresh',['id'=>$id,'reference'=>$reference]);echo '<button>Inspect stored provider result</button></form>';if(self::can('configure')){self::form('resolve',['id'=>$id,'reference'=>$reference]);echo '<h3>Local simulator evidence</h3><p>Only for an uncertain timeout simulation. This does not contact a real provider or move money.</p><label>Definitive test outcome<select name="outcome"><option value="succeeded">Confirmed success</option><option value="failed">Confirmed failure</option><option value="canceled">Confirmed cancellation</option></select></label>';self::input('reason','Reconciliation evidence / reason','text','','required maxlength="500"');echo '<button>Record simulator evidence & reconcile</button></form>';}}
            if(CommerceComplimentaryService::isOrder(self::$db,self::$org,$id))echo '<p>Complimentary admission · zero-price staff settlement · no payment provider attempt.</p>';
            if(self::can('refund')&&$o['state']==='paid'){self::form('refund',['id'=>$id,'reference'=>$reference]);self::input('reason',CommerceComplimentaryService::isOrder(self::$db,self::$org,$id)?'Complimentary cancellation reason':'Full simulated refund reason','text','','required maxlength="500"');echo '<button>'.(CommerceComplimentaryService::isOrder(self::$db,self::$org,$id)?'Cancel complimentary order & release seats':'Refund full sandbox order').'</button></form>';}
            foreach(self::rows('SELECT t.*,l.description,l.category FROM commerce_tickets t JOIN commerce_order_lines l ON l.order_id=t.order_id AND l.seat_key=t.seat_key AND l.organization_id=t.organization_id WHERE t.organization_id=? AND t.order_id=?',[self::$org,$id]) as $t){echo '<section class="commerce-record"><h3>'.self::e($t['description']).'</h3><p>'.self::e($t['category'].' · '.$t['state']).' · '.($t['checked_in_at']?'Admitted':'Not admitted').'</p>';if(self::can('refund')&&$t['state']==='valid'&&!$t['checked_in_at']){self::form('revoke',['id'=>$id,'ticket'=>$t['id'],'reference'=>$reference]);self::input('reason','Revocation reason','text','','required maxlength="500"');echo '<button>Revoke ticket without releasing sold seat</button></form>';}echo '</section>';}
        }else{
            echo '<h3>Recent sandbox orders</h3><div class="commerce-records">';foreach(self::rows('SELECT public_reference,state,total_minor,currency,created_at FROM commerce_orders WHERE organization_id=? ORDER BY id DESC LIMIT 50',[self::$org]) as $o)echo '<div class="commerce-record"><a href="'.self::e(self::url('orders',['reference'=>$o['public_reference']])).'">'.self::e($o['public_reference']).'</a> · '.self::e($o['state']).' · '.self::money((int)$o['total_minor'],$o['currency']).' · '.self::e($o['created_at']).'</div>';echo '</div>';
        }
    }

    private static function extension(string $tab):void
    {
        self::catalog();
    }
    private static function extensionCommand(string $action):string{throw new RuntimeException('Unknown Commerce action.');}
}
